import { useMatchMedia } from '@hexa-ui/theme';
import React, { forwardRef, useCallback, useLayoutEffect, useRef, useState } from 'react';
import { useOnClickOutside } from '../../hooks/useOnClickOutside/useOnClickOutside';
import DatePickerInput, { DatePickerInputProps } from '../input/DatePickerInput/DatePickerInput';
import { DatePickerBaseProps } from './components/DatePickerBase';
import { DatePickerBase } from './components/DatePickerBase/DatePickerBase';
import { DatePickerMobile } from './components/DatePickerMobile';

import { DatePickerModal, DatePickerWrapper } from './DatePicker.styles';
import { setUTCHoursForDate } from '../calendar/utils/setUTCHoursForDate';

export type DatePickerProps = {
  value?: Date[];
  onChange?: (value?: Date[]) => void;
  onSave?: (value?: Date[]) => void;
  width?: string | number;
  align?: 'left' | 'right';
  inputLegend?: string;
  inputDisabled?: boolean;
} & Omit<DatePickerBaseProps, 'onSave' | 'onReset' | 'onClose'> &
  Omit<
    DatePickerInputProps,
    'onChange' | 'value' | 'onClick' | 'mode' | 'ref' | 'onReset' | 'legend' | 'disabled' | 'prefix'
  >;

export const DatePicker = forwardRef(
  (
    {
      value,
      onChange,
      callToActionSection,
      onSave,
      mode = 'single',
      width,
      numberOfMonths,
      align = 'left',
      hint,
      label,
      inputLegend,
      required,
      optionalText = '(Optional)',
      hasError,
      inputDisabled = false,
      errorText,
      labelProps,
      placeholder,
      id,
      ...rest
    }: DatePickerProps,
    forwardedRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => {
    const [isPickerVisible, setIsPickerVisible] = useState(false);
    const [datePickerSelection, setDatePickerSelection] = useState<Array<Date> | undefined>(value);
    const datePickerRef = useRef<HTMLDivElement>(null);

    const [isMobile] = useMatchMedia(['mobile']);

    useLayoutEffect(() => {
      if (isPickerVisible) {
        setDatePickerSelection(value);
      }
    }, [isPickerVisible, value]);

    const hideDatePicker = useCallback(() => {
      setIsPickerVisible(false);
    }, []);

    useOnClickOutside(datePickerRef, hideDatePicker);

    const handleSelectDate = (newValue?: Date[]) => {
      setDatePickerSelection(newValue);

      if (!callToActionSection || isMobile) {
        onChange?.(newValue);

        if (mode === 'single') {
          setIsPickerVisible(false);
        }
      }
    };

    const handleSave = () => {
      onSave?.(datePickerSelection);
      setIsPickerVisible(false);
    };

    const handleReset = () => {
      setDatePickerSelection(value);
    };

    const handleFocus = () => {
      if (mode === 'single') {
        setIsPickerVisible(false);
      } else {
        setIsPickerVisible(true);
      }
    };

    const handleClose = () => {
      setIsPickerVisible(false);
      handleReset();
    };

    return (
      <DatePickerWrapper ref={forwardedRef}>
        <DatePickerInput
          onClick={() => setIsPickerVisible(true)}
          value={value}
          onChange={(newValue) => {
            const newDate = setUTCHoursForDate(newValue) as Date[];
            handleSelectDate(newDate);
          }}
          onFocus={handleFocus}
          mode={mode}
          width={width}
          labelProps={{ ...labelProps, htmlFor: id }}
          label={label}
          hint={hint}
          legend={inputLegend}
          hasError={hasError}
          disabled={inputDisabled}
          required={required}
          errorText={errorText}
          optionalText={optionalText}
          placeholder={placeholder}
          data-testid="date-picker-input"
          customLocale={rest.customLocale}
        />
        {isPickerVisible && (
          <>
            {isMobile ? (
              <DatePickerMobile
                onChange={handleSelectDate}
                onClose={handleClose}
                value={datePickerSelection}
                mode={mode}
                {...rest}
              />
            ) : (
              <DatePickerModal align={align}>
                <DatePickerBase
                  onChange={handleSelectDate}
                  onSave={handleSave}
                  onClose={handleClose}
                  value={datePickerSelection}
                  defaultValue={value}
                  callToActionSection={callToActionSection}
                  onReset={handleReset}
                  mode={mode}
                  numberOfMonths={mode === 'range' ? 2 : numberOfMonths}
                  ref={datePickerRef}
                  {...rest}
                />
              </DatePickerModal>
            )}
          </>
        )}
      </DatePickerWrapper>
    );
  }
);
